import type { AgentAsset, ConvertOptions } from "../ir.js";
import { assertId, literal, todo } from "./common.js";

export function renderSubagent(agent: AgentAsset, options: ConvertOptions): string {
  assertId(agent.id, "subagent");
  const notes = agent.findings.filter((finding) => finding.status !== "mapped")
    .map((finding) => todo(`${finding.field}: ${options.lang === "zh" ? finding.message : finding.messageEn}`));
  return [
    '// Generated by cc-to-cursor-agent. Review the migration report before running.',
    'import { defineAgent } from "@grok/agent-sdk";',
    "", "export default defineAgent({",
    `  description: ${literal(agent.description)},`,
    ...(agent.model ? [`  model: ${literal(agent.model)},`] : []),
    ...notes,
    "});", "",
  ].join("\n");
}
